SOURCES={'alice':'https://alice.yandex.ru/support/ru/station/skills/','alexa':'https://digprjsurvey.amazon.com/csad/help/node/GGYT25QXMYBECH2E','alexa_widgets':'https://digprjsurvey.amazon.com/csad/help/node/GGVNRBH8CKP9PRC2'}
GROUPS=[row for row in GROUPS if row[0]!='creative_companion']
def build():
    rows=[]
    for category,path,examples in GROUPS:
        items=examples.split('|');assert len(items)==20,(category,len(items))
        for i,question in enumerate(items):
            quick=resolve_quick(question) if path=='native' else None
            control=path=='native' and (mode_intent(question) or closing_intent(question))
            status='local_path' if control or quick and quick.executor!='unavailable' else 'needs_phrase_route' if path=='native' else 'conditional_path' if path in {'conversation','visual','expert'} else 'not_connected_or_restricted'
            requirements={'conversation':['owner_live_backend_budget','quality_policy'],'visual':['source_availability','image_consent_if_generated','render_ack'],'expert':['verified_model','task_confirmation','cli_quota','isolation'],'integration':['specific_service_or_privacy_implementation']}.get(path,[])
            rows.append({'id':category+'-'+str(i+1).zfill(2),'category':category,'request':question,'path':path,'readiness':status,
                'executor':quick.executor if quick else 'conversation_modes' if control else None,'intent':quick.intent if quick else None,'requirements':requirements,'acoustic_verified':False,'competitor_reference_scope':'category_inspiration_not_individual_equivalence'})
    assert len(rows)==400 and len({r['request'] for r in rows})==400
    return {'version':1,'sources':SOURCES,'note':'400 authored scenarios, not 400 unique executable tools or a claim of Alice/Alexa parity. Runtime ACL, budgets and actual integrations remain authoritative. Conditional language tasks are not 200 real model tests.','scenarios':rows}
if __name__=='__main__':
    result=build();target=ROOT/'services/brain/assistant-skills.json';target.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    from collections import Counter
    print(json.dumps({'scenarios':len(result['scenarios']),'readiness':dict(Counter(r['readiness'] for r in result['scenarios']))}))
